public class ReportGeneratorBackgroundService : BackgroundService
{
    private readonly ILogger<ReportGeneratorBackgroundService> _logger;
    private readonly IServiceProvider _services;

    public ReportGeneratorBackgroundService(ILogger<ReportGeneratorBackgroundService> logger, IServiceProvider services)
    {
        _logger = logger;
        _services = services;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                using var scope = _services.CreateScope();
                var reportService = scope.ServiceProvider.GetRequiredService<IReportService>();
                var result = await reportService.GenerateReportAsync();
                _logger.LogInformation("Report generated: {Result}", result);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error generating report");
            }

            await Task.Delay(TimeSpan.FromSeconds(30), stoppingToken);
        }
    }
}

