// Custom middleware that measures request processing time and adds a header
public class ResponseTimeMiddleware
{
    private readonly RequestDelegate _next;

    public ResponseTimeMiddleware(RequestDelegate next) => _next = next;

    public async Task InvokeAsync(HttpContext context)
    {
        var start = Stopwatch.GetTimestamp(); // start timing

        // Register a callback to set the header just before the response starts
        context.Response.OnStarting(state =>
        {
            var httpContext = (HttpContext)state!;
            var elapsedMs = (Stopwatch.GetTimestamp() - start) * 1000.0 / Stopwatch.Frequency;
            httpContext.Response.Headers["X-Response-Time-ms"] = elapsedMs.ToString("0.##");
            return Task.CompletedTask;
        }, context);

        await _next(context); // invoke the rest of the pipeline
    }
}

