// Bind the "Smtp" configuration section to SmtpOptions.
builder.Services.Configure<SmtpOptions>(
    builder.Configuration.GetSection(SmtpOptions.Section));

var app = builder.Build();

app.MapGet("/smtp", (Microsoft.Extensions.Options.IOptions<SmtpOptions> opts) =>
{
    // Return the configured host.
    return Results.Ok(opts.Value.Host);
});

app.Run();

public class SmtpOptions
{
    public const string Section = "Smtp";

    public string? Host { get; set; }
    public int Port { get; set; }
}

