using System.ComponentModel.DataAnnotations;
using Microsoft.Extensions.Options;

var builder = WebApplication.CreateBuilder(args);

// Register and validate PaymentOptions
builder.Services.AddOptions<PaymentOptions>()
    .BindConfiguration(PaymentOptions.SectionName)
    .ValidateDataAnnotations()
    .ValidateOnStart();

var app = builder.Build();

app.MapGet("/", (IOptions<PaymentOptions> options) =>
    $"API Key: {options.Value.ApiKey ?? "<missing>"}");

app.Run();

public class PaymentOptions
{
    public const string SectionName = "Payment";

    [Required]
    public string? ApiKey { get; set; }
}

// Program.cs
var builder = WebApplication.CreateBuilder(args);

// Add CORS policy that allows only https://example.com
builder.Services.AddCors(options =>
{
    options.AddPolicy("OnlyExampleCom", policy =>
    {
        policy.WithOrigins("https://example.com")
              .AllowAnyHeader()
              .AllowAnyMethod();
    });
});

var app = builder.Build();

// Apply the CORS policy globally before routing
app.UseCors("OnlyExampleCom");

// GET /api/data endpoint
app.MapGet("/api/data", () => Results.Ok(new { Message = "Hello from the API" }));

app.Run();

// Program.cs

var builder = WebApplication.CreateBuilder(args);

// Add ProblemDetails services (adds the RFC‑7807 formatter)
builder.Services.AddProblemDetails();

var app = builder.Build();

// Global exception handling – produces RFC‑7807 JSON for any unhandled exception
app.UseExceptionHandler("/error");

// Minimal‑API endpoint that deliberately throws
app.MapGet("/boom", (HttpContext ctx) =>
{
    throw new InvalidOperationException("Boom!");
});

app.MapGet("/error", (HttpContext ctx) =>
{
    // The exception handler middleware has already set the response status.
    // ProblemDetails middleware will format the response as RFC‑7807 JSON.
    return Results.Problem();
});

app.Run();

