// Program.cs

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// In‑memory product list
var productList = new List<Product>
{
    new Product(1, "Apple"),
    new Product(2, "Banana"),
    new Product(3, "Orange")
};

// Create a route group for the product API
var products = app.MapGroup("/api/v1/products");

// Apply an endpoint filter to the whole group that logs each request
products.AddEndpointFilter(async (context, next) =>
{
    var logger = context.HttpContext.RequestServices.GetRequiredService<ILogger<Program>>();
    logger.LogInformation("Calling {Method} {Path}",
        context.HttpContext.Request.Method,
        context.HttpContext.Request.Path);

    // Continue to the next filter / endpoint handler
    var result = await next(context);
    return result;
});

// GET /api/v1/products – list all products
products.MapGet("/", () => Results.Ok(productList));

// GET /api/v1/products/{id} – get a single product
products.MapGet("/{id:int}", (int id) =>
{
    var product = productList.FirstOrDefault(p => p.Id == id);
    return product is not null ? Results.Ok(product) : Results.NotFound();
});

app.Run();

// Simple product model
record Product(int Id, string Name);

// Program.cs
string[] summaries = new[]
{
    "Freezing", "Bracing", "Chilly", "Cool", "Mild", "Warm", "Balmy", "Hot", "Sweltering", "Scorching"
};

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

app.MapGet("/weather", async () =>
{
    // Simulate a slow external service
    await Task.Delay(200);

    var forecast = Enumerable.Range(1, 5).Select(index =>
        new WeatherForecast(
            DateOnly.FromDateTime(DateTime.Now.AddDays(index)),
            Random.Shared.Next(-20, 55),
            summaries[Random.Shared.Next(summaries.Length)]))
        .ToArray();

    return forecast;
});

app.Run();

record WeatherForecast(DateOnly Date, int TemperatureC, string Summary);

