using Microsoft.AspNetCore.RateLimiting;
using System.Threading.RateLimiting;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddRateLimiter(options =>
{
    options.AddFixedWindowLimiter("QuotePolicy", opt =>
    {
        opt.PermitLimit = 10;
        opt.Window = TimeSpan.FromMinutes(1);
        opt.QueueProcessingOrder = QueueProcessingOrder.OldestFirst;
        opt.QueueLimit = 0;
    });
    options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
});

var app = builder.Build();

app.UseRouting();
app.UseRateLimiter();

app.MapGet("/api/quote", () => Results.Ok("Your quote"))
   .RequireRateLimiting("QuotePolicy");

app.Run();

// Program.cs
var builder = WebApplication.CreateBuilder(args);

// Register typed HttpClient GitHubClient
builder.Services.AddHttpClient<GitHubClient>(client =>
{
    client.BaseAddress = new Uri("https://api.github.com/");
    client.DefaultRequestHeaders.UserAgent.ParseAdd("MyApp"); // required by GitHub
});

var app = builder.Build();

// Endpoint: GET /repos/{owner}
app.MapGet("/repos/{owner}", async (string owner, GitHubClient client) =>
{
    var response = await client.GetReposAsync(owner);
    // Forward the response from GitHub directly
    return response;
});

app.Run();

public class GitHubClient
{
    private readonly HttpClient _http;
    public GitHubClient(HttpClient http) => _http = http;
    // GET /repos/{owner}
    public Task<HttpResponseMessage> GetReposAsync(string owner) =>
        _http.GetAsync($"/repos/{owner}");
}
